{
  "lecture": [
    {
      "etiquette": "F21",
      "R1": {
        "valeur": 1,
        "passage": "composantes rares couvertes aux retenues au moins 2 fois celles du bras sans lentille sur la somme des 12 mondes (et au moins +3 en valeur absolue)"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes par strate de masse, aux étages des propositions brutes, des représentants et des retenues ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "ne masque rien de l'archive (rejet établi : aucun masquage), n'impose aucun quota de formes et n'ajoute aucune prime"
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 1,
        "passage": "la vue de chaque proposeur reçoit, après l'archive, une ligne : \" Examiner en priorité les épisodes dont les traits sont dans [description publique de la strate] ; toute carte reste admise. \""
      },
      "R6": {
        "valeur": 1,
        "passage": "12 mondes × 2 bras × 4 proposeurs × 1 appel ; ordre de quelques dizaines de dollars ; devis avant feu vert."
      },
      "R7": {
        "valeur": 1,
        "passage": "Un acteur qui ajoute des modèles de frontière sans partition recouvre le même bassin global ; la partition par strates publiques scellée est une propriété de la composition de l'organisme"
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F22",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées couvertes augmente d'au moins 25 % par rapport à la course de référence"
      },
      "R2": {
        "valeur": 1,
        "passage": "nombre de composantes plantées couvertes, lu par l'oracle après la course ; témoin : une modification tirée au hasard, au même coût"
      },
      "R3": {
        "valeur": 0,
        "motif": "Réduire m d'un tiers sans réduire les comparaisons ni ajuster la procédure lève le contrôle des comparaisons multiples, sans nommer cette objection ni y répondre."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche ne nomme aucune garantie restant démontrable après la réduction de m, ni le nul auquel elle s'appliquerait."
      },
      "R5": {
        "valeur": 0,
        "motif": "La réduction d'un tiers ne précise ni l'arrondi de m entier ni le traitement des groupes lorsque leur nombre dépasse le nouveau m."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars d'appels par graine"
      },
      "R7": {
        "valeur": 0,
        "motif": "Dire que l'archive grandit plus ou moins vite selon m n'explique pas pourquoi sa réduction augmenterait la couverture vraie plutôt que les fausses promotions."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F23",
      "R1": {
        "valeur": 1,
        "passage": "Au même plafond de dollars, les composantes certifiées couvertes par les retenues augmentent d'au moins 25 % en relatif."
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle lu une fois après la course : composantes couvertes aux trois étages et profondeur de chaîne atteinte."
      },
      "R3": {
        "valeur": 1,
        "passage": "L'archive est le seul canal légitime de ce qu'une génération lègue : aucun verdict n'est servi, la garde contre les copies fait le travail de redirection, sans récompense de nouveauté."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 1,
        "passage": "Dans chacune, un appel par proposeur en session neuve, trois cartes, puis la chaîne complète : gardien, regroupement, juge, test de mort, sélection, mise à jour de l'archive."
      },
      "R6": {
        "valeur": 1,
        "passage": "Bon marché d'abord : un modèle peu cher, 20 mondes, 2 bras plus le placebo, environ 500 appels, soit quelques dizaines de dollars."
      },
      "R7": {
        "valeur": 1,
        "passage": "Enfin, une composante conditionnelle n'est trouvable qu'une fois sa condition archivée, et la mise à jour plus fréquente raccourcit ce délai à dépense égale."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F24",
      "R1": {
        "valeur": 1,
        "passage": "à budget de tirages égal, au moins 20 % de composantes plantées couvertes en plus par génération que l'ordre actuel"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes par génération (oracle, lu après la course) ; témoin à coût égal : ordre tiré au hasard"
      },
      "R3": {
        "valeur": 0,
        "motif": "Les scores des juges à modèle déterminent quelles cartes accèdent au test de mort avant épuisement du budget, intervenant ainsi dans la sélection sans réponse à l'objection."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche ne précise aucune garantie statistique restant démontrable ni le nul concerné."
      },
      "R5": {
        "valeur": 0,
        "motif": "Le tournoi n'est pas entièrement spécifié : mises à jour Elo, nombre de comparaisons, seuil des mieux classées et règle de tirage des paires manquent."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars de juges par génération"
      },
      "R7": {
        "valeur": 0,
        "motif": "Qualifier les cartes les mieux cotées de prometteuses ne relie pas la préférence des juges à une augmentation de la couverture vraie mesurée par l'oracle."
      },
      "N": {
        "valeur": "C1",
        "passage_fiche": "Des juges à modèle comparent les cartes deux à deux : les mieux classées en débats à plusieurs tours, les autres en une seule comparaison",
        "passage_catalogue": "par **comparaisons appariées** : débats à plusieurs tours pour les mieux classées, une seule comparaison pour les autres"
      }
    },
    {
      "etiquette": "F25",
      "R1": {
        "valeur": 1,
        "passage": "À budget de jetons et d'appels aux modèles strictement égal, le nombre de fausses découvertes ou copies promues de formes `si_sinon` et `melange` baisse d'au moins 50 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle après la course : nombre de composantes plantées vraies couvertes (D2 sur les retenues) et nombre de lois fausses ou copies promues"
      },
      "R3": {
        "valeur": 1,
        "passage": "Tout le reste (règle de Benjamini et Hochberg sur les valeurs e des groupes, budget de tirages) est inchangé."
      },
      "R4": {
        "valeur": 1,
        "passage": "vraisemblance prédictive séquentielle afin de maintenir démontrablement l'espérance de la valeur e au plus égale à 1 sous le nul"
      },
      "R5": {
        "valeur": 0,
        "motif": "La fiche ne donne pas la construction exacte de la valeur e contre le nul composite étendu ; ajuster des poids sur une moitié puis évoquer une vraisemblance prédictive ne la définit pas."
      },
      "R6": {
        "valeur": 1,
        "passage": "L'expérience décisive la moins chère qui la tuerait se joue sur processeur seul (quelques heures de calcul, zéro appel de modèle)"
      },
      "R7": {
        "valeur": 0,
        "motif": "L'élargissement du nul explique le rejet de copies par morceaux, mais pas l'augmentation de couverture vraie annoncée à tirages constants, puisqu'il peut aussi réduire la puissance."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
